import org.apache.commons.jxpath.JXPathException;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedList;

import static org.junit.jupiter.api.Assertions.*;

public class ExpandCollectionTests {

    @Test
    public void testExpandCollectionWithNullInput() {
        Object result = ValueUtils.expandCollection(null, 5);
        assertNull(result);
    }

    @Test
    public void testExpandCollectionWithObjectArray() {
        String[] input = {"a", "b"};
        Object result = ValueUtils.expandCollection(input, 4);
        assertNotNull(result);
        assertInstanceOf(String[].class, result);
        String[] expanded = (String[]) result;
        assertEquals(4, expanded.length);
        assertEquals("a", expanded[0]);
        assertEquals("b", expanded[1]);
        assertNull(expanded[2]);
        assertNull(expanded[3]);
    }

    @Test
    public void testExpandCollectionWithPrimitiveArray() {
        int[] input = {1, 2};
        Object result = ValueUtils.expandCollection(input, 3);
        assertNotNull(result);
        assertInstanceOf(int[].class, result);
        int[] expanded = (int[]) result;
        assertEquals(3, expanded.length);
        assertEquals(1, expanded[0]);
        assertEquals(2, expanded[1]);
        assertEquals(0, expanded[2]);
    }

    @Test
    public void testExpandCollectionWithArrayList() {
        Collection<String> input = new ArrayList<>();
        input.add("x");
        int initialSize = input.size();
        Object result = ValueUtils.expandCollection(input, 3);

        assertSame(input, result, "Should return the same collection instance");
        assertEquals(3, input.size());
        assertEquals("x", input.iterator().next());
        for (int i = initialSize; i < 3; i++) {
            assertNull(new ArrayList<>(input).get(i));
        }
    }

    @Test
    public void testExpandCollectionWithLinkedList() {
        Collection<Integer> input = new LinkedList<>();
        input.add(10);
        int initialSize = input.size();
        Object result = ValueUtils.expandCollection(input, 5);

        assertSame(input, result);
        assertEquals(5, input.size());
        assertEquals(10, input.iterator().next());
        Object[] array = input.toArray();
        for (int i = initialSize; i < 5; i++) {
            assertNull(array[i]);
        }
    }

    @Test
    public void testExpandCollectionWithSameSizeArray() {
        Double[] input = {1.1, 2.2};
        Object result = ValueUtils.expandCollection(input, 2);
        assertNotNull(result);
        assertInstanceOf(Double[].class, result);
        Double[] expanded = (Double[]) result;
        assertEquals(2, expanded.length);
        assertEquals(1.1, expanded[0]);
        assertEquals(2.2, expanded[1]);
    }

    @Test
    public void testExpandCollectionWithSameSizeCollection() {
        Collection<String> input = new ArrayList<>();
        input.add("a");
        input.add("b");
        Object result = ValueUtils.expandCollection(input, 2);

        assertSame(input, result);
        assertEquals(2, input.size());
    }

    @Test
    public void testExpandCollectionShrinkingArrayThrowsException() {
        String[] input = {"a", "b", "c"};
        JXPathException ex = assertThrows(JXPathException.class, () -> {
            ValueUtils.expandCollection(input, 2);
        });
        assertTrue(ex.getMessage().contains("is not an expansion"));
    }

    @Test
    public void testExpandCollectionShrinkingCollectionThrowsException() {
        Collection<Integer> input = new ArrayList<>();
        input.add(1);
        input.add(2);
        input.add(3);
        JXPathException ex = assertThrows(JXPathException.class, () -> {
            ValueUtils.expandCollection(input, 1);
        });
        assertTrue(ex.getMessage().contains("is not an expansion"));
    }

    @Test
    public void testExpandCollectionUnsupportedTypeThrowsException() {
        Object input = "Not a collection";
        JXPathException ex = assertThrows(JXPathException.class, () -> {
            ValueUtils.expandCollection(input, 5);
        });
        assertTrue(ex.getMessage().contains("Cannot turn"));
        assertTrue(ex.getMessage().contains("into a collection"));
    }
}

