        assertNotNull(iterator);
        assertTrue(iterator instanceof CollectionChildNodeIterator);
    }

    @Test
    void testChildIterator_WholeCollection_Reverse() {
        NodeIterator iterator = listPointer.childIterator(nodeNameTest, true, null);
        assertNotNull(iterator);
        assertTrue(iterator instanceof CollectionChildNodeIterator);
    }

    @Test
    void testChildIterator_SpecificIndex_List() {
        listPointer.setIndex(0);

        NodeIterator iterator = listPointer.childIterator(nodeNameTest, false, null);
        assertNotNull(iterator);
        assertFalse(iterator instanceof CollectionChildNodeIterator);
    }

    @Test
    void testChildIterator_SpecificIndex_Array() {
        arrayPointer.setIndex(1);

        NodeIterator iterator = arrayPointer.childIterator(nodeTypeTest, true, null);
        assertNotNull(iterator);
        assertFalse(iterator instanceof CollectionChildNodeIterator);
    }

    @Test
    void testChildIterator_NullParentConstructor() {
